<?php
require_once __DIR__ . '/../includes/auth.php'; require_login(); $active_menu='reports';$rows=all_rows("SELECT st.staff_id,CONCAT(st.first_name,' ',st.last_name) staff_name,st.position,COUNT(a.appointment_id) appointment_count,COALESCE(SUM(a.status='Completed'),0) completed_count,COALESCE(SUM(a.status='Cancelled'),0) cancelled_count,COALESCE(SUM(CASE WHEN p.payment_status IN ('Paid','Partially Paid') THEN p.amount ELSE 0 END),0) revenue_generated FROM staff st LEFT JOIN appointments a ON a.staff_id=st.staff_id LEFT JOIN payments p ON p.appointment_id=a.appointment_id GROUP BY st.staff_id,st.first_name,st.last_name,st.position ORDER BY revenue_generated DESC,appointment_count DESC");$page_title='Staff Performance Report';require __DIR__.'/../includes/header.php';
?>
<h2 class="print-heading">Staff Performance Report</h2><?php require __DIR__.'/../includes/report_nav.php';?><div class="card shadow-sm table-card"><div class="table-responsive"><table class="table table-hover align-middle mb-0"><thead><tr><th>Staff member</th><th>Position</th><th>Appointments</th><th>Completed</th><th>Cancelled</th><th>Revenue generated</th></tr></thead><tbody><?php foreach($rows as $row):?><tr><td><?=e($row['staff_name'])?></td><td><?=e($row['position'])?></td><td><?= (int)$row['appointment_count']?></td><td><?= (int)$row['completed_count']?></td><td><?= (int)$row['cancelled_count']?></td><td><?=money($row['revenue_generated'])?></td></tr><?php endforeach;?></tbody></table></div></div><?php require __DIR__.'/../includes/footer.php';
